test('starts with initial queue', () => {
  const { result } = renderHook(() => useQueue([1, 2]));
  expect(result.current.queue).toEqual([1, 2]);
});

test('enqueue appends to back', () => {
  const { result } = renderHook(() => useQueue([]));
  act(() => result.current.enqueue('a'));
  act(() => result.current.enqueue('b'));
  expect(result.current.queue).toEqual(['a', 'b']);
});

test('dequeue removes front item', () => {
  const { result } = renderHook(() => useQueue(['a', 'b', 'c']));
  act(() => result.current.dequeue());
  expect(result.current.queue).toEqual(['b', 'c']);
});

test('peek reads front item without removing', () => {
  const { result } = renderHook(() => useQueue(['x', 'y']));
  expect(result.current.peek).toBe('x');
  expect(result.current.queue.length).toBe(2);
});

