solution:
import { useState } from 'react';

export function useQueue(initial = []) {
  const [queue, setQueue] = useState(initial);
  return {
    queue,
    enqueue: (item) => setQueue(q => [...q, item]),
    dequeue: () => setQueue(q => q.slice(1)),
    peek: queue[0],
    size: queue.length,
  };
}
